<script setup lang="ts">
import { ref } from 'vue'; import { useWorkspace } from '../stores/workspace'
const ws=useWorkspace(), draft=ref(''); const send=async()=>{const v=draft.value.trim();if(!v)return;draft.value='';await ws.send(v)}
</script>
<template><div class="assistant-layout"><section class="card chat-card"><div class="chat-head"><div><span class="eyebrow">FUTURELEDGER AI</span><h1>财务助手</h1></div><span class="mode-pill" :class="ws.mode"><i></i>{{ws.mode==='mock'?'演示模式':'API 连接'}}</span></div><div class="chat-body"><div v-if="!ws.messages.length" class="welcome-message"><div class="assistant-avatar">✦</div><h2>你好，我是你的财务助手</h2><p>你可以问我账单、订阅或未来现金流问题。</p><div class="suggestions"><button v-for="q in ['这个月餐饮花了多少？','工资晚 5 天会怎样？','帮我看看有哪些订阅']" :key="q" @click="draft=q">{{q}}　↗</button></div></div><div v-for="(m,i) in ws.messages" :key="i" class="message" :class="m.role"><div v-if="m.role==='assistant'" class="assistant-avatar small">✦</div><p>{{m.text}}</p></div></div><form class="composer" @submit.prevent="send"><textarea v-model="draft" rows="2" placeholder="输入你的问题…" @keydown.enter.exact.prevent="send"></textarea><div class="composer-foot"><span>演示数据 · AI 不会直接执行资金操作</span><button class="send-button" :disabled="!draft.trim()">发送　↑</button></div></form></section><aside class="card assistant-aside"><h3>快捷场景</h3><button @click="draft='分析本月支出'">▤　分析本月支出</button><button @click="draft='如果工资晚 5 天到账呢？'">⌁　模拟工资延迟</button><button @click="draft='检查我的订阅'">↻　检查订阅状态</button><div class="aside-note"><span>ⓘ</span><p>AI 提供分析建议。所有资金操作仍需你确认，并由服务端执行安全检查。</p></div><div class="service-status"><i></i><span>本地演示工作台<small>当前不会提交银行操作</small></span></div></aside></div></template>
